const items = $input.all();
const body = items[0].json.body || items[0].json;
const text = body.text || '';
const parts = text.split(' ');
const startDate = parts[0] || '';
const endDate = parts[1] || startDate;
const reason = parts.slice(2).join(' ') || 'Personal';
const userId = body.user_id || '';
const userName = body.user_name || '';

return [{json: {
  userId,
  userName,
  startDate,
  endDate,
  reason,
  requestId: `pto-${Date.now()}`,
  requestedAt: new Date().toISOString()
}}];

parameters.text:
:palm_tree: *PTO Request*

*From:* <@{{ $json.userId }}>
*Dates:* {{ $json.startDate }} to {{ $json.endDate }}
*Reason:* {{ $json.reason }}
*Request ID:* {{ $json.requestId }}

Please approve or deny via the webhook:
- Approve: `/approve {{ $json.requestId }}`
- Deny: `/deny {{ $json.requestId }}`

